"""Derive the worked ctl-X fixture; --check compares every generated byte.
Uses the conformance JCS/envelope tooling, never interpreter imports.
"""
import argparse
import json
import runpy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DIR = ROOT / "conformance/fixtures/controlled-action-09"
HASH = runpy.run_path(str(ROOT / "conformance/tools/draft_examples.py"))
jcs, sha = HASH["jcs"], HASH["sha"]
LIBRARY = "5de4e4995350313e50217880ba1b95de39cd043283b726337d4894efb005d197"


def derive(version):
    signature = dict(abi=version, args=[], bounds=[], **{"in": [1]}, kind="perm_action", mem=[], mut=[1], tier="q")
    flip_sig = dict(signature, **{"in": []})
    symbols = {"0": dict(interface_hash="0"*64, kind="perm_action", name="controlled", signature=signature),
               "1": dict(interface_hash="0"*64, kind="perm_action", name="flip", signature=flip_sig)}
    functions = "perm_action @controlled (t:wire mut) (c:wire in) () () ()\n^entry():\nctl c action_call @flip (t) () () ()\nperm_action @flip (t:wire mut) () () () ()\n^entry():\nx t"
    header = "bennett-object " + " ".join(k+"="+version for k in ("isa", "object", "launch", "sched", "cert", "coverage", "target")) + " ptr_width=32"
    def source():
        return header + "\n\nsection symbols\n" + jcs(symbols) + "\n\nsection functions\n" + functions + "\n"
    hashes, _, _ = HASH["hashes"](source().rstrip("\n"))
    for sym in symbols.values():
        sym["interface_hash"] = hashes[sym["name"]]
    base = source()
    root, flip = hashes["controlled"], hashes["flip"]
    target = json.loads((ROOT / "conformance/cases/E/E-epsilon-zero-exact/target.json").read_text())
    target["gates"] = [dict(op="x", controls=dict(min=1, max=1), classes=["fast"], cost=dict(time=1), epsilon=0)]
    target["classes"]["fast"]["capacity"] = 2
    path = [dict(symbol=root, point="entry:0", iteration=[]), dict(symbol=flip, point="entry:0", iteration=[])]
    selector = dict(path=path, step="*", phase="*", generated=0)
    schedule = dict(bindings=dict(closure_hash=root, target_hash=sha(jcs(target)), region="controlled", variant="forward", inherited_controls=0,
                                 budget=[0,0,0,0], params_hash=sha("[]"), epsilon=0, scheduler=dict(name="worked-ctl", version="1")),
                    entries=[dict(selector, kind="gate", gate=dict(realisation="native", epsilon_share=0)),
                             dict(selector, kind="start", start=dict(time=0))])
    if version == "0.9":
        schedule["bindings"]["expansion"] = dict(name="ref", version="0.9", hash=LIBRARY)
    frame = dict(slots=[dict(id="mut:0", role="mut", width=1, **{"class":"fast"}), dict(id="in:0", role="in", width=1, **{"class":"fast"})],
                 scratch=[], history=[], borrow=[], ancillae=[])
    if version == "0.8":
        frame = dict(interface=[dict(role="mut", width=1, **{"class":"fast"}), dict(role="in", width=1, **{"class":"fast"})],
                     scratch={}, retained_history=0, borrow={}, scheme_ancillae={})
    domain = dict(bundles=[dict(name=n, width=1, lo=0, hi=1) for n in ("t", "c")], borrowed=[], regions=[])
    def tup(t, c):
        return dict(bundles=[str(t),str(c)], borrowed=[], regions=[])
    rows = [dict(before=tup(t,c), after=tup(t^c,c)) for t in range(2) for c in range(2)]
    subject = dict(closure_hash=root, variant="forward", inherited_controls=0, schedule_hash=sha(jcs(schedule)))
    claim = dict(kind="exhaustive", label="proof", domain=domain, expected=dict(table=rows))
    numerical = dict(kind="numerical", subject=subject, metric="operator_norm", precision_bits=128, bound=0)
    invocation = dict(args=[], budget=["0"]*4)
    if version == "0.9":
        claim["subject"] = subject
    else:
        claim["expected"] = dict(table=[[t^c,c] for t in range(2) for c in range(2)])
    claims = [claim, numerical] if version == "0.9" else [claim]
    verification = dict(oracle=None, borrow_frames=[], inverse_pairs=[], unitary=[1] if version == "0.9" else [], channel=[],
                        fault_rate=dict(domain=dict(bundles=[],borrowed=[],regions=[]),faults_by_code={},undefined_excluded=0,layout_dependent_excluded=0))
    region = dict(kind="perm_action", signature=signature, bounds=[], frame=frame, resources=dict(time=1,peak_qubits=2,qubit_second=2),
                  gates_used=dict(x=dict(count=1)), claims=claims, verification=verification, cleanup={},
                  error={"forward:0":dict(local=dict(operator_norm=0),inclusive=dict(operator_norm=0))}, definedness_assumptions=[])
    cert = dict(versions={k:version for k in ("isa","object","launch","sched","cert","coverage","target")},
                bindings=dict(object_hash=sha(base),interface_hash=root,closure_hash=root,reference_program_hash=root,
                              dialect_mapping_version="worked-ctl.1",target_hash=sha(jcs(target)),schedule_hash=sha(jcs(schedule))),
                producer=dict(name="conformance", version="1",materialisation=dict(llvm_version="none",pipeline="worked-ctl",normaliser_version="1")),
                regions={root:region}, composition=dict(multiplicities={root+":forward:0":1,flip+":forward:1":1},
                                                        epsilon_total=dict(diamond=0),method="sum_over_multiplicities"))
    # Each realised context has its own signature/frame and controlled numerical claim.
    if version == "0.9":
        cert["bindings"]["invocation"] = invocation
        child_subject = dict(subject, closure_hash=flip, inherited_controls=1)
        child = dict(region, signature=flip_sig, frame=dict(frame, slots=frame["slots"][:1]),
                     resources=dict(time=1,peak_qubits=2,qubit_second=2),
                     claims=[dict(numerical,subject=child_subject)], verification=dict(verification,unitary=[0]),
                     error={"forward:1":dict(local=dict(operator_norm=0),inclusive=dict(operator_norm=0))})
        cert["regions"][flip] = child
    full = base + "\nsection schedule\n" + jcs(schedule) + "\n\nsection certificate\n" + jcs(cert) + "\n"
    return dict(source=full, target=target, schedule=schedule, certificate=cert, frame=frame,
                leaves=[dict(path=path,step="*",phase="*",generated=0,gate="x",wires=["t[0]"],controls=["c[0]"],
                             target_entry=0,start=0,end=1,**{"class":"fast"})])


def artifacts():
    d = derive("0.9")
    files = {"controlled.bisa":d.pop("source").encode()}
    files.update({k+".json":jcs(v).encode() for k,v in d.items()})
    files["compat-0.8.bisa"] = derive("0.8")["source"].encode()
    return files


if __name__ == "__main__":
    parser=argparse.ArgumentParser()
    parser.add_argument("--check",action="store_true")
    args=parser.parse_args()
    if not args.check:
        DIR.mkdir(parents=True,exist_ok=True)
    for name, raw in artifacts().items():
        if args.check:
            assert (DIR/name).read_bytes()==raw, name
        else:
            (DIR/name).write_bytes(raw)
    print("controlled-action fixture: object, target, leaf, schedule, frames and certificate byte-exact")
